const recentRunExists = `-- name: RecentRunExists :one
SELECT EXISTS(SELECT 1 FROM ops.run WHERE source=$1 AND catalog=$2 AND window_start <= $3::date AND window_end >= LEAST($4::date, (started_at AT TIME ZONE 'UTC')::date) AND started_at > now() - ($5::integer * interval '1 hour'))
`

type RecentRunExistsParams struct {
	Source      string      `json:"source"`
	Catalog     string      `json:"catalog"`
	WindowStart pgtype.Date `json:"window_start"`
	WindowEnd   pgtype.Date `json:"window_end"`
	Hours       int32       `json:"hours"`
}

// A moving end date only requires coverage through the previous run's UTC day.
// Requiring today's end would bypass weekly cadence every time the date changes.
func (q *Queries) RecentRunExists(ctx context.Context, arg RecentRunExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, recentRunExists,
		arg.Source,
		arg.Catalog,
		arg.WindowStart,
		arg.WindowEnd,
		arg.Hours,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

